import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Summary"]
src = vals["Sheet1"]

allowed_statuses = {"completed", "not completed"}
totals = {}

for row in src.iter_rows(min_row=2, values_only=True):
    if len(row) < 4:
        continue

    status, name, typ, amt = row[0], row[1], row[2], row[3]

    if status is None or name is None or typ is None or amt is None:
        continue
    if isinstance(amt, bool):
        continue

    status_key = str(status).strip().lower()
    if status_key not in allowed_statuses:
        continue

    try:
        amount = float(amt)
    except (TypeError, ValueError):
        continue

    key = (str(name).strip().lower(), str(typ).strip().upper())
    totals[key] = totals.get(key, 0.0) + amount

headers = [
    ws.cell(row=1, column=2).value,
    ws.cell(row=1, column=3).value,
]

for r in range(2, 7):
    name = ws.cell(row=r, column=1).value

    if name is None:
        ws.cell(row=r, column=2).value = None
        ws.cell(row=r, column=3).value = None
        continue

    name_key = str(name).strip().lower()

    for c, header in enumerate(headers, start=2):
        type_key = str(header).strip().upper() if header is not None else ""
        value = totals.get((name_key, type_key), 0.0)

        if float(value).is_integer():
            value = int(value)

        ws.cell(row=r, column=c).value = value

wb.save(OUT)

print("totals:", totals)
print("written:", [[ws.cell(row=r, column=c).value for c in (2, 3)] for r in range(2, 7)])
